for sh in wb.worksheets:
    for row in sh.iter_rows(values_only=True):
        for v in row:
            if isinstance(v,str) and v.startswith('#'):
                errs.append((sh.title,v))
                break
        if errs:
            break
print('Errors found?', errs[:10])
